import { defineConfig } from "vite";
import solid from "vite-plugin-solid";
import wasm from "vite-plugin-wasm";

// `vite-plugin-wasm` lets us `import` the wasm-pack output as a
// regular ES module — Vite handles the WebAssembly.instantiate dance
// and exposes a typed module surface generated by wasm-bindgen.
//
// `vite-plugin-solid` is the Solid.js JSX transform.
export default defineConfig({
  plugins: [solid(), wasm()],

  // Phase 1.16a: dev server runs on 5173 (Vite default). Production
  // build target is < 2 MB gzipped — measured against `dist/` after
  // `npm run build`. Bundle optimisation is 1.16c.
  //
  // Phase 1.16c3b: dev proxy for the Lakko services. The auth
  // service has no CORS layer (no need — production terminates
  // everything at nginx and routes by path). Calling the Rust
  // service directly from the browser would hit a same-origin
  // wall, so the dev server forwards `/api/auth/*` →
  // `http://127.0.0.1:8081/*` (the auth service's default bind).
  // Production nginx will route the same `/api/auth/*` path; the
  // client-side `AuthClient` uses a single relative base URL.
  server: {
    port: 5173,
    strictPort: true,
    proxy: {
      "/api/auth": {
        target: "http://127.0.0.1:8081",
        changeOrigin: true,
        rewrite: (p) => p.replace(/^\/api\/auth/, ""),
      },
      // 1.16d2: lakko-svc-discovery defaults to 127.0.0.1:8084.
      // Same routing principle as /api/auth — production nginx
      // will forward the same path; the relative client base
      // URL works in both environments.
      "/api/discovery": {
        target: "http://127.0.0.1:8084",
        changeOrigin: true,
        rewrite: (p) => p.replace(/^\/api\/discovery/, ""),
      },
      // 1.16d3c: lakko-svc-ds defaults to 127.0.0.1:8082.
      // POST /ds/mailbox/{pseudonym_hex}/messages publishes a
      // raw-bytes payload (ContactRequest wire bytes); GET
      // returns base64-encoded payloads plus a cursor.
      "/api/ds": {
        target: "http://127.0.0.1:8082",
        changeOrigin: true,
        rewrite: (p) => p.replace(/^\/api\/ds/, ""),
      },
      // 1.19c1: lakko-svc-storage defaults to 127.0.0.1:8083.
      // PUT/GET/HEAD /blob/<sha256_hex> carries ciphertext as
      // an octet-stream body. Production nginx forwards the
      // same path; the client-side `StorageClient` uses a
      // single relative base URL in both environments.
      "/api/storage": {
        target: "http://127.0.0.1:8083",
        changeOrigin: true,
        rewrite: (p) => p.replace(/^\/api\/storage/, ""),
      },
      // 1.20b: lakko-svc-push-gw defaults to 127.0.0.1:8085.
      // POST /push/register / /push/unregister carries the
      // device pseudonym + provider + (base64-encoded) token.
      // GET /pow/challenge issues the per-call PoW seed. The
      // SW side calls these via the same `/api/push` prefix.
      "/api/push": {
        target: "http://127.0.0.1:8085",
        changeOrigin: true,
        rewrite: (p) => p.replace(/^\/api\/push/, ""),
      },
      // Phase 4: lakko-svc-channels defaults to 127.0.0.1:8086.
      // Carries opaque ChannelPost bytes (POST /v1/.../posts),
      // HPKE seed envelopes (80 bytes per subscriber), and
      // the subscribe handshake. Production nginx routes the
      // same `/api/channels/*` path to the upstream.
      "/api/channels": {
        target: "http://127.0.0.1:8086",
        changeOrigin: true,
        rewrite: (p) => p.replace(/^\/api\/channels/, ""),
      },
    },
  },

  build: {
    target: "es2022",
    sourcemap: true,
    // Top-level `await` in the WASM init flow needs ES2022.
    rollupOptions: {
      output: {
        // Splitting the WASM chunk separately lets the browser cache
        // it across page navigations.
        manualChunks: {
          "lakko-wasm": ["../../apps/web/wasm/lakko_ffi_wasm"],
        },
      },
    },
  },

  // The wasm-pack output goes into `apps/web/wasm/` (npm run
  // `build:wasm`). Treat it as a normal source dependency so Vite
  // re-bundles when it changes.
  optimizeDeps: {
    exclude: ["@lakko/ffi-wasm"],
  },
});
